    if not resources:
        return [0, 0]

    # Determine if we can secure a resource (arrive strictly earlier than opponent)
    my_early = []
    for r in resources:
        rx, ry = int(r[0]), int(r[1])
        ds = cheb(sx, sy, rx, ry)
        do = cheb(ox, oy, rx, ry)
        if ds + 0 < do:
            my_early.append((rx, ry, ds, do))
    has_early = len(my_early) > 0

    best = None
    for dx, dy, nx, ny in legal:
        if has_early:
            # Prefer resources we are now strictly closer to, then minimize our distance; tie-break by opponent distance
            best_val = None
            for rx, ry, ds0, do0 in my_early:
                ds = cheb(nx, ny, rx, ry)
                if ds >= do0:
                    continue
                val = (ds, do0, rx + ry)  # deterministic tie-break
                if best_val is None or val < best_val:
                    best_val = val
            if best_val is None:
                # If can't keep the early advantage, still move toward the most favorable early target by race gap
                gap_best = None
                for r in resources:
                    rx, ry = int(r[0]), int(r[1])
                    ds = cheb(nx, ny, rx, ry)
                    do = cheb(ox, oy, rx, ry)
                    gap = do - ds
                    val = (-gap, ds, do)  # maximize gap => minimize negative
                    if gap_best is None or val < gap_best:
                        gap_best = val
                score = (0, gap_best)  # category
            else:
                score = (1, best_val)
        else:
            # No guaranteed early picks: choose move that maximizes average race advantage across reachable resources (cheb)
            best_metric = None
            for r in resources:
                rx, ry = int(r[0]), int(r[1])
                ds = cheb(nx, ny, rx, ry)
                do = cheb(ox, oy, rx, ry)
                gap = do - ds
                # Encourage getting closer overall but prioritize positive gap
                metric = (-gap, ds, (rx - (w // 2)) * (rx - (w // 2)) + (ry - (h // 2)) * (ry - (h // 2)))
                if best_metric is None or metric < best_metric:
                    best_metric = metric
            score = (2, best_metric)

        if best is None or score < best[0] or (score == best[0] and (dx, dy) < (best[1][0], best[1][1])):
            best = (score, (dx, dy))

    return [int(best[1][0]), int(best[1][1])]

